  fetchPromise: Promise<Response>,
  headers: RequestHeaders,
  signal: AbortSignal | undefined
): Promise<T> & { _debugInfo?: Array<any> } {
  if (
    process.env.__NEXT_DEV_SERVER &&
    process.env.__NEXT_SERVER_COMPONENTS_HMR_CANCELLATION &&
    signal
